import React, { useState, useEffect, useContext } from "react";
import axios from "axios";
import GeneralContext from "./GeneralContext";
import { Tooltip, Grow } from "@mui/material";
import {
  BarChartOutlined,
  KeyboardArrowDown,
  KeyboardArrowUp,
  MoreHoriz,
} from "@mui/icons-material";
const { watchlist } = require("../data/data");
import { DoughnutChart } from "./DoughnoutChart";
import "./LiveWatchList.css"; // optional custom CSS

const LiveWatchList = () => {
  const [stocks, setStocks] = useState(initialList);
  const [search, setSearch] = useState("");

  // ✅ Live stock updates (±2% random)
  useEffect(() => {
    const interval = setInterval(() => {
      setStocks((prev) =>
        prev.map((stock) => {
          const changePercent = (Math.random() * 4 - 2).toFixed(2);
          const newPrice = stock.price + (stock.price * changePercent) / 100;

          return {
            ...stock,
            price: parseFloat(newPrice.toFixed(2)),
            percent:
              (changePercent > 0 ? "+" : "") + changePercent + "%",
            isDown: changePercent < 0,
          };
        })
      );
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  // ✅ Filter by search
  const filteredStocks = stocks.filter((s) =>
    s.name.toLowerCase().includes(search.toLowerCase())
  );

  // ✅ Chart Data
  const labels = filteredStocks.map((stock) => stock.name);
  const data = {
    labels,
    datasets: [
      {
        label: "Live Prices",
        data: filteredStocks.map((s) => s.price),
        backgroundColor: [
          "rgba(255, 99, 132, 0.5)",
          "rgba(54, 162, 235, 0.5)",
          "rgba(255, 206, 86, 0.5)",
          "rgba(75, 192, 192, 0.5)",
          "rgba(153, 102, 255, 0.5)",
          "rgba(255, 159, 64, 0.5)",
          "rgba(199, 99, 255, 0.5)",
          "rgba(140, 200, 255, 0.5)",
        ],
        borderColor: [
          "rgba(255, 99, 132, 1)",
          "rgba(54, 162, 235, 1)",
          "rgba(255, 206, 86, 1)",
          "rgba(75, 192, 192, 1)",
          "rgba(153, 102, 255, 1)",
          "rgba(255, 159, 64, 1)",
        ],
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="watchlist-container">
      {/* 🔍 Search Bar */}
      <div className="search-container">
        <input
          type="text"
          name="search"
          id="search"
          placeholder="Search eg: INFY, TCS, RELIANCE..."
          className="search"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <span className="counts">{filteredStocks.length} / 50</span>
      </div>

      {/* 📈 Stock List */}
      <ul className="list">
        {filteredStocks.map((stock, index) => (
          <LiveWatchListItem stock={stock} key={index} />
        ))}
      </ul>

      {/* 🍩 Doughnut Chart */}
      <DoughnutChart data={data} />
    </div>
  );
};

export default LiveWatchList;

const LiveWatchListItem = ({ stock }) => {
  const [showActions, setShowActions] = useState(false);

  return (
    <li
      onMouseEnter={() => setShowActions(true)}
      onMouseLeave={() => setShowActions(false)}
    >
      <div className="item">
        <p className={stock.isDown ? "down" : "up"}>{stock.name}</p>

        <div className="itemInfo">
          <span className="percent">{stock.percent}</span>
          {stock.isDown ? (
            <KeyboardArrowDown className="down" />
          ) : (
            <KeyboardArrowUp className="up" />
          )}
          <span className="price">₹ {stock.price.toFixed(2)}</span>
        </div>
      </div>

      {showActions && <LiveWatchListActions uid={stock.name} />}
    </li>
  );
};

const LiveWatchListActions = ({ uid }) => {
  const generalContext = useContext(GeneralContext);

  const handleBuyClick = () => {
    generalContext.openTradeWindow(uid, "buy");
  };

  const handleSellClick = () => {
    generalContext.openTradeWindow(uid, "sell");
  };

  return (
    <span className="actions">
      <Tooltip title="Buy (B)" placement="top" arrow TransitionComponent={Grow}>
        <button className="buy" onClick={handleBuyClick}>
          Buy
        </button>
      </Tooltip>

      <Tooltip title="Sell (S)" placement="top" arrow TransitionComponent={Grow}>
        <button className="sell" onClick={handleSellClick}>
          Sell
        </button>
      </Tooltip>

      <Tooltip title="Analytics (A)" placement="top" arrow TransitionComponent={Grow}>
        <button className="action">
          <BarChartOutlined className="icon" />
        </button>
      </Tooltip>

      <Tooltip title="More" placement="top" arrow TransitionComponent={Grow}>
        <button className="action">
          <MoreHoriz className="icon" />
        </button>
      </Tooltip>
    </span>
  );
};
